#include <string>

class Solution {
public:
    std::string breakPalindrome(std::string palindrome) {
        int n = palindrome.size();
        if (n <= 1) return "";
        for (int i = 0; i < n / 2; ++i) {
            if (palindrome[i] != 'a') {
                palindrome[i] = 'a';
                return palindrome;
            }
        }
        palindrome[n - 1] = 'b';
        return palindrome;
    }
};

class Solution {
    public String breakPalindrome(String palindrome) {
        int n = palindrome.length();
        if (n <= 1) return "";
        char[] chars = palindrome.toCharArray();
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] != 'a') {
                chars[i] = 'a';
                return new String(chars);
            }
        }
        chars[n - 1] = 'b';
        return new String(chars);
    }
}

var breakPalindrome = function(palindrome) {
    const n = palindrome.length;
    if (n <= 1) return "";
    const chars = palindrome.split("");
    for (let i = 0; i < Math.floor(n / 2); i++) {
        if (chars[i] !== "a") {
            chars[i] = "a";
            return chars.join("");
        }
    }
    chars[n - 1] = "b";
    return chars.join("");
};
